        void Availability(){Set("EditLabelGroup",grid.CurrentRow!=null||marked.Count>0);Set("RLabelGroup",grid.CurrentRow!=null||marked.Count>0);bool any=LabelBrowse.FilterMembers(catalog,prefix.Text,suffix.Text).Count>0;Set("EditAllLabels",any);Set("RAllLabels",any);Set("PickCheckedLabels",marked.Count>0);Set("IsolateCheckedLabels",marked.Count>0);Set("LabelLibrary",factory!=null);Set("InspectMain",factory!=null);Set("SamplesMain",factory!=null);Set("CreateMain",creation!=null&&creation.ReadyToCreate);}
        void Set(string name,bool enabled){var list=Controls.Find(name,true);if(list.Length>0)list[0].Enabled=enabled;}
        void Filter()
        {
            string keep=grid.CurrentRow==null?null:((LabelGroup)grid.CurrentRow.DataBoundItem).Key;filtering=true;try{grid.DataSource=LabelBrowse.Rows(catalog,SystemMode,search.Text,prefix.Text,suffix.Text,sort,ascending);foreach(DataGridViewRow row in grid.Rows){var info=(LabelGroup)row.DataBoundItem;row.Cells["Marked"].Value=marked.Contains(info.Key);if(info.Key==keep)grid.CurrentCell=row.Cells[1];}foreach(DataGridViewColumn column in grid.Columns)column.HeaderCell.SortGlyphDirection=column.Name==sort?(ascending?SortOrder.Ascending:SortOrder.Descending):SortOrder.None;}finally{filtering=false;}Counts();
        }
        void Counts(){int visible=grid.Rows.Cast<DataGridViewRow>().Count(r=>marked.Contains(((LabelGroup)r.DataBoundItem).Key));all.CheckState=visible==0?CheckState.Unchecked:visible==grid.Rows.Count?CheckState.Checked:CheckState.Indeterminate;count.Text=grid.Rows.Count+" cụm hiện • đã tích "+marked.Count+" (ẩn: "+(marked.Count-visible)+") • "+LabelBrowse.FilterMembers(catalog,prefix.Text,suffix.Text).Count+" đường thỏa lọc Layer / "+catalog.Members.Count+" đường có nhãn";Availability();}
        LabelScope Scope(bool every,bool ticksOnly=false){var row=grid.CurrentRow==null?null:grid.CurrentRow.DataBoundItem as LabelGroup;return new LabelScope{All=every,SystemMode=SystemMode,Keys=marked.Count>0?marked.OrderBy(x=>x).ToArray():ticksOnly||row==null?new string[0]:new[]{row.Key},LayerPrefix=prefix.Text.Trim(),LayerSuffix=suffix.Text.Trim(),Fingerprint=catalog.Fingerprint};}
        void Edit(bool every,bool r)
        {
            var scope=Scope(every);var members=LabelRules.Select(catalog,scope);if(members.Count==0)return;string title=every?"MỌI NHÃN THỎA LỌC LAYER":marked.Count>0?marked.Count+" CỤM ĐÃ TÍCH":"CỤM ĐANG CHỌN";
            using(var form=new LabelEditForm(members,catalog.Definitions,palette,context,title,r))while(form.ShowDialog(this)==DialogResult.OK){bool success=false;try{success=apply(scope,form.Value);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Chưa ghi DWG");}if(success){catalog=reload();marked.Clear();Filter();break;}}
        }
